'use strict';
const $=id=>document.getElementById(id), clone=x=>JSON.parse(JSON.stringify(x));
const names={time:'Tiempo',battery:'Batería',oxygen:'Oxígeno simulado',water:'Agua',nutrition:'Demanda energética'};
const statuses={SUCCESS:'Plan calculado',INFEASIBLE:'Misión no factible con estas restricciones',SEARCH_LIMIT_REACHED:'Búsqueda interrumpida; factibilidad desconocida',INVALID_INPUT:'Entrada inválida'};
const policies={balanced:'Equilibrada',minimum_time:'Tiempo mínimo',terrain_caution:'Cautela de terreno'};
const decisions={CONTINUE:'Continuar',RETURN:'Regresar',REVIEW_CONTINUATION_UNKNOWN:'Revisar: continuación desconocida',REVIEW_RETURN_UNCONFIRMED:'Revisar: regreso sin confirmar',REVIEW_INVALID_INPUT:'Revisar las entradas'};
const phaseNames={outbound:'Ida',activity:'Actividad',inbound:'Regreso'};
const advancedNames={agent_radius_m:'Radio del agente (m)',safety_margin_m:'Margen geométrico (m)',max_slope_deg:'Pendiente máxima (°)',near_obstacle_m:'Proximidad a obstáculos (m)',slope_weight:'Peso de pendiente (adimensional)',risk_weight:'Peso de riesgo (adimensional)',roughness_weight:'Peso de rugosidad (adimensional)',proximity_weight:'Peso de proximidad (adimensional)',speed_m_per_min:'Velocidad (m/min)',uphill_speed_penalty:'Penalización de velocidad en ascenso (adimensional)',roughness_speed_penalty:'Penalización de rugosidad (adimensional)',uphill_effort_penalty:'Penalización de esfuerzo en ascenso (adimensional)',climb_battery_wh_per_m:'Batería de ascenso (Wh/m)',hazard_cost_weight:'Peso de penalización del terreno (adimensional)',battery_cost_weight:'Peso de batería (min/Wh)'};
let catalog,config,bundle=null,selected=0,revision=0,resultRevision=-1,busy=false,sequence=0,selectionSequence=0,activeCell=[3,3];
const fmt=x=>x===null||x===undefined?'—':typeof x==='number'?x.toLocaleString('es',{maximumFractionDigits:4}):String(x);
const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(text,kind=''){$('status').textContent=text;$('status').className=kind;}
function stale(){revision++;selectionSequence++;if(bundle){notice('Resultados anteriores · Entradas modificadas; pendiente de recalcular.','stale');$('mapGrid').dataset.stale='true';drawMap();}else if(busy){notice('Calculando una configuración anterior · Las entradas actuales requieren otro cálculo.','stale');}}
function numberInput(label,value,change,attrs={}){const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');i.type='number';i.step='any';i.value=value;Object.entries(attrs).forEach(([k,v])=>i.setAttribute(k,v));i.addEventListener('input',()=>{change(i.value===''?null:Number(i.value));stale();});l.append(i);return l;}
function textInput(label,value,change){const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');i.value=value;i.addEventListener('input',()=>{change(i.value);stale();});l.append(i);return l;}
function renderConfig(){
  $('map').value=config.map;$('agent').value=config.agent;$('activityStatus').value=config.activity_status;$('activity').value=config.activity_min;$('activity').disabled=config.activity_status==='completed';$('scenario').value=config.scenario;$('factor').value=config.factor;$('factor').disabled=config.scenario==='nominal';$('limit').value=config.max_labels;
  $('mass').value=config.personal.body_mass_kg??'';$('height').value=config.personal.height_m??'';$('personalPanel').hidden=config.agent!=='astronaut';
  $('profileInfo').textContent=`${config.profile.profile_id} · v${config.profile.version} · SIMULADO. Valores editables sin calibración física.`;
  $('resourceInputs').replaceChildren();
  for(const [k,r] of Object.entries(config.profile.resources)){
    const box=document.createElement('div');box.className='resourceBlock';const title=document.createElement('h3');title.textContent=`${names[k]} (${r.unit==='simulated_u'?'unidades simuladas':r.unit})`;box.append(title);
    if(r.status==='not_applicable'){box.append('No aplica');$('resourceInputs').append(box);continue;}
    if(!['time','battery'].includes(k)){
      const label=document.createElement('label');label.textContent='Tratamiento experimental';const select=document.createElement('select');select.innerHTML='<option value="modeled">Modelado</option><option value="excluded">Exclusión experimental explícita</option>';select.value=r.status;
      select.onchange=()=>{if(select.value==='excluded'){config.profile.resources[k]={status:'excluded',unit:r.unit,reason:'Exclusión experimental declarada por el usuario'};delete config.remaining[k];}else{config.profile.resources[k]=clone(catalog.defaults[config.map][config.agent].profile.resources[k]);config.remaining[k]=config.profile.resources[k].capacity;}stale();renderConfig();};label.append(select);box.append(label);
    }
    if(r.status==='excluded'){box.append(textInput('Motivo de exclusión (obligatorio)',r.reason,v=>r.reason=v));}
    else{const fields=document.createElement('div');fields.className='fields';fields.append(numberInput('Capacidad original',r.capacity,v=>r.capacity=v),numberInput('Saldo actual',config.remaining[k],v=>config.remaining[k]=v),numberInput('Reserva absoluta',r.reserve,v=>r.reserve=v),numberInput(`Tasa de movimiento (${r.unit}/min)`,r.movement_rate,v=>r.movement_rate=v,{...(k==='time'?{readonly:'readonly'}:{})}),numberInput(`Tasa de actividad (${r.unit}/min)`,r.activity_rate,v=>r.activity_rate=v,{...(k==='time'?{readonly:'readonly'}:{})}));box.append(fields);}
    $('resourceInputs').append(box);
  }
  $('advanced').replaceChildren();for(const group of ['mobility','motion']){const fields=document.createElement('div');fields.className='fields';for(const [k,v]of Object.entries(config.profile[group]))fields.append(numberInput(advancedNames[k]||k,v,n=>config.profile[group][k]=n));$('advanced').append(fields);}
  $('pointFields').replaceChildren();for(const key of ['base','current','goal']){const wrap=document.createElement('div');const title=document.createElement('label');title.textContent={base:'Base',current:'Posición manual',goal:'Objetivo'}[key];wrap.append(title);const f=document.createElement('div');f.className='fields';['Fila','Col.'].forEach((name,index)=>f.append(numberInput(name,config[key][index],n=>{config[key][index]=n;drawMap();},{min:0,max:6,step:1,'aria-label':`${title.textContent} ${name}`})));wrap.append(f);$('pointFields').append(wrap);}
  const map=catalog.maps[config.map];$('mapDescription').textContent=map.description;$('frameHelp').textContent=`Norte arriba, este a la derecha. Cada celda: ${map.resolution_m} m; ancho: ${map.columns*map.resolution_m} m. X interno hacia este, Y interno hacia sur. ${config.map==='ctx'?'E = −16 + X; N = 16 − Y (m).':'E = X; N = −Y (m), marco sintético.'}`;$('provenance').textContent=JSON.stringify(map.provenance,null,2);drawMap();
}
function reset(){config=clone(catalog.defaults[$('map').value][$('agent').value]);stale();renderConfig();}
function records(){if(!bundle?.result)return[];return bundle.result.alternatives||[bundle.result.continuation,bundle.result.returning];}
function drawMap(){if(!config)return;const grid=$('mapGrid');grid.replaceChildren();const map=catalog.maps[config.map];for(const data of map.cells){const [r,c]=data.cell,b=document.createElement('button');b.className='cell';b.dataset.cell=`${r},${c}`;b.setAttribute('aria-label',`Celda ${r},${c}`);const height=data.height_m;const all=map.cells.map(x=>x.height_m).filter(x=>x!==null),range=Math.max(...all)-Math.min(...all);const tone=height===null?18:28+(range?(height-Math.min(...all))/range*18:7);b.style.setProperty('--shade',`hsl(157 12% ${tone}%)`);
    if(config.obstacles.some(x=>x[0]===r&&x[1]===c))b.classList.add('blocked');if(data.risk)b.classList.add('penalty');const tags=[];for(const key of ['base','current','goal'])if(config[key][0]===r&&config[key][1]===c)tags.push({base:'B',current:'P',goal:'O'}[key]);b.innerHTML=`<small>${r},${c}</small>${tags.length?`<span>${tags.join('·')}</span>`:''}`;b.onclick=()=>chooseCell(data.cell);b.onfocus=()=>showCell(data);b.onmouseenter=()=>showCell(data);b.onkeydown=e=>{const d={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]}[e.key];if(d){e.preventDefault();grid.querySelector(`[data-cell="${r+d[0]},${c+d[1]}"]`)?.focus();}};grid.append(b);}
  const result=records()[selected];if(result?.plan && bundle.configuration.map===config.map && resultRevision===revision){
    const p=result.plan,svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('routes');svg.setAttribute('viewBox','0 0 700 700');const goal=p.goal_index,segments={outbound:goal===null?[]:p.path.slice(0,goal+1),inbound:goal===null?p.path:p.path.slice(goal)};for(const [phase,path]of Object.entries(segments)){if($('phase').value!=='both'&&$('phase').value!==phase)continue;const line=document.createElementNS(svg.namespaceURI,'polyline');line.setAttribute('points',path.map(([r,c])=>`${(c+.5)*100},${(r+.5)*100}`).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke',phase==='outbound'?'#83e9dd':'#ffbb80');line.setAttribute('stroke-width',phase==='outbound'?'10':'5');if(phase==='inbound')line.setAttribute('stroke-dasharray','13 10');svg.append(line);}grid.append(svg);
  }
  $('points').textContent=`Base (${config.base}) · Posición (${config.current}) · Objetivo (${config.goal})`;$('perturbation').textContent=`${config.obstacles.length} obstáculos SIMULADOS. CTX original intacto. Seleccione el modo de obstáculos y una celda para alternarlos.`;
}
function showCell(data){activeCell=data.cell;$('coordinates').textContent=`Celda (${data.cell}) · XY interno [este,sur] (${data.planner_xy_m.map(fmt).join('; ')}) m · E/N (${data.east_north_m.map(fmt).join('; ')}) m · ${config.map==='ctx'?'Altura CTX absoluta':'Altura sintética'} ${fmt(data.height_m)} m`;
}
async function post(url,data){const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Object.assign(new Error(result.message),{payload:result});return result;}
async function chooseCell(cell){showCell(catalog.maps[config.map].cells.find(x=>x.cell.toString()===cell.toString()));const mode=$('mode').value;if(mode==='inspect')return;if(mode==='obstacle'){const i=config.obstacles.findIndex(x=>x.toString()===cell.toString());if(i<0)config.obstacles.push(cell);else config.obstacles.splice(i,1);stale();drawMap();return;}const token=++selectionSequence,rev=revision;try{const r=await post('/api/inspect',{configuration:clone(config),cell});if(token!==selectionSequence||rev!==revision)return;if(!r.traversable){$('coordinates').textContent+=` · ${r.message}`;return;}config[mode]=cell;stale();renderConfig();}catch(e){$('coordinates').textContent+=` · ${e.message}`;}}
async function calculate(action){if(busy)return;busy=true;const token=++sequence,startRevision=revision,sent=clone(config);$('compare').disabled=$('evaluate').disabled=true;notice('Calculando con el motor Python… Los resultados visibles son anteriores. Puede inspeccionar y editar la configuración.');try{const value=await post('/api/calculate',{configuration:sent,action});if(token!==sequence)return;bundle=value;resultRevision=startRevision;selected=0;renderResults();if(startRevision!==revision)notice('Resultados anteriores · La configuración cambió durante el cálculo; pendiente de recalcular.','stale');else notice('Cálculo finalizado · Resultado vinculado a las entradas actuales.');drawMap();}catch(e){if(token===sequence){resultRevision=-1;bundle={configuration:sent,error:e.payload||{message:e.message},result:null};$('alternatives').replaceChildren();$('detail').replaceChildren();$('recommendation').textContent='';$('coincidence').textContent='';notice(`${e.payload?.status||'ERROR'} · ${e.message}`,'error');$('trace').textContent='Solicitud rechazada: exportación disponible de las entradas enviadas y del error. No hay plan confirmado.';exportsEnabled();drawMap();}}finally{if(token===sequence){busy=false;$('compare').disabled=$('evaluate').disabled=false;}}}
function exportsEnabled(){for(const id of ['exportConfig','exportResult','exportWaypoints'])$(id).disabled=!bundle;}
function renderResults(){const r=bundle.result,list=records();exportsEnabled();$('recommendation').textContent=r.decision?`${decisions[r.decision]} · ${r.decision}. ${r.message}`:`Recomendación: ${r.recommendation?policies[r.recommendation]+' ('+r.recommendation+')':'Sin alternativa SUCCESS'}`;$('coincidence').textContent=r.coincident_routes?`${r.distinct_successful_routes} recorridos distintos calculados. Grupos coincidentes: ${r.coincident_routes.map(x=>x.join(' + ')).join(' | ')||'ninguno'}`:r.rule;
  $('alternatives').innerHTML='<div class="cards">'+list.map((a,i)=>`<button class="alt ${i===selected?'selected':''}" data-alt="${i}"><strong>${r.decision?(a.mode==='continue'?'Continuar vía objetivo':'Regreso directo'):policies[a.policy]}</strong><span class="badge ${a.status}">${a.status} · ${statuses[a.status]}</span><span>${a.plan?`${fmt(a.plan.total.distance_m)} m · ${fmt(a.plan.total.duration_min)} min · ${fmt(a.plan.total.resources.battery.consumed)} Wh`:'Sin ruta confirmada'}</span><span>Etiquetas generadas: ${fmt(a.search_metrics.generated_labels)}</span></button>`).join('')+'</div>';
  document.querySelectorAll('[data-alt]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.alt);renderResults();drawMap();});renderDetail();$('trace').textContent=`Cálculo ${bundle.calculation_id} · ${bundle.created_utc} · ${bundle.configuration.agent} · ${bundle.configuration.scenario} · revisión ${bundle.terrain.revision_sha256}. Las descargas corresponden a este cálculo, aunque las entradas cambien.`;
}
function resourceTable(resources){return '<div class="tableWrap"><table><thead><tr><th>Recurso</th><th>Saldo al solicitar</th><th>Consumo futuro</th><th>Saldo final</th><th>Reserva absoluta</th><th>Margen sobre reserva</th></tr></thead><tbody>'+Object.entries(resources).map(([k,v])=>`<tr><td>${names[k]} (${v.unit})</td>${v.status==='modeled'?['capacity','consumed','remaining','reserve','margin_above_reserve'].map(key=>`<td>${fmt(v[key])}</td>`).join(''):`<td colspan="5">${v.status==='excluded'?'Excluido experimentalmente: '+escape(v.reason):'No aplica'}</td>`}</tr>`).join('')+'</tbody></table></div>';}
function renderDetail(){const a=records()[selected];if(!a)return;let html=`<h3>${policies[a.policy]} · ${a.policy}</h3><p class="${a.status}">${statuses[a.status]}.</p><p>${escape(a.message)} <code>${a.reason_code}</code></p>`;html+='<p class="help">Criterio de política: '+({balanced:'Pesos originales de tiempo, penalización de terreno y batería.',minimum_time:'Pesos externos de terreno y batería = 0.',terrain_caution:'Peso de terreno elevado a max(4, 2 × original).'}[a.policy])+'</p>';
  if(a.plan){html+=resourceTable(a.plan.total.resources);html+='<details><summary>Inspeccionar fases y eventos de consumo</summary>';for(const phase of ['outbound','activity','inbound']){const v=a.plan.phases[phase];html+=`<h3>${phaseNames[phase]}</h3><p>${fmt(v.duration_min)} min · ${fmt(v.distance_m)} m</p>`+'<p>'+Object.entries(v.consumed).map(([k,n])=>names[k]+': '+fmt(n)+' '+a.plan.total.resources[k].unit).join(' · ')+'</p>';}html+='<div class="tableWrap"><table><tr><th>Evento</th><th>Fase</th><th>Celda inicio → fin</th><th>Duración (min)</th><th>Incrementos de recursos</th></tr>'+a.plan.events.map(e=>`<tr><td>${e.index} · ${escape(e.kind)}</td><td>${phaseNames[e.phase]}</td><td>(${e.start_cell}) → (${e.end_cell})</td><td>${fmt(e.duration_min)}</td><td>${Object.entries(e.incremental).map(([k,v])=>names[k]+': '+fmt(v)).join(' · ')}</td></tr>`).join('')+'</table></div><p class="help">Unidades de incrementos: tiempo min, batería Wh, O₂ unidades simuladas, agua L, demanda kcal. La actividad completada no genera evento de actividad.</p></details>';}
  html+='<details><summary>Perfil original, efectivo y pesos</summary><pre>'+escape(JSON.stringify({original:a.request?.profile,effective:a.effective_profile,weights:a.policy_weights},null,2))+'</pre></details>';$('detail').innerHTML=html;
}
function download(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('map').onchange=reset;$('agent').onchange=reset;$('load').onclick=reset;
$('activityStatus').onchange=()=>{config.activity_status=$('activityStatus').value;if(config.activity_status==='completed')config.activity_min=0;stale();renderConfig();};
for(const [id,key]of [['activity','activity_min'],['factor','factor'],['limit','max_labels']])$(id).oninput=()=>{config[key]=$(id).value===''?null:Number($(id).value);stale();};
$('scenario').onchange=()=>{config.scenario=$('scenario').value;stale();renderConfig();};for(const [id,key]of [['mass','body_mass_kg'],['height','height_m']])$(id).oninput=()=>{config.personal[key]=$(id).value===''?null:Number($(id).value);stale();};
$('mode').onchange=()=>{selectionSequence++;};$('phase').onchange=drawMap;$('restore').onclick=()=>{config.obstacles=[];stale();drawMap();};$('compare').onclick=()=>calculate('compare');$('evaluate').onclick=()=>calculate('evaluate');
$('exportConfig').onclick=()=>download({ui_schema:'6.0',configuration:bundle.configuration,request:bundle.request,terrain:bundle.terrain,provenance:bundle.provenance,perturbations:bundle.perturbations},'mission-configuration.json');$('exportResult').onclick=()=>download(bundle,'mission-result.json');$('exportWaypoints').onclick=()=>download({ui_schema:'6.0',calculation_id:bundle.calculation_id,terrain:bundle.terrain,frames:bundle.frames,units:bundle.units,provenance:bundle.provenance,perturbations:bundle.perturbations,waypoints:bundle.waypoints||[]},'mission-waypoints.json');
fetch('/api/catalog').then(r=>{if(!r.ok)throw new Error('No se pudo cargar el catálogo');return r.json();}).then(data=>{catalog=data;config=clone(catalog.defaults.ctx.astronaut);renderConfig();}).catch(e=>notice(e.message,'error'));
